PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE transactions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    dealDate TEXT,
                    dealYear TEXT,
                    dealMonth TEXT,
                    dealDay TEXT,
                    sggCd TEXT,
                    regionName TEXT,
                    umdNm TEXT,
                    jibun TEXT,
                    aptNm TEXT,
                    floor INTEGER,
                    excluUseAr REAL,
                    areaType TEXT,
                    dealAmount INTEGER,
                    buildYear TEXT,
                    dealType TEXT,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                , cdealType TEXT, cdealDay TEXT);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_transactions_unique
                ON transactions (
                    dealYear, dealMonth, dealDay, sggCd, umdNm, jibun, aptNm, floor, excluUseAr, dealAmount
                );
CREATE INDEX idx_transactions_date_apt
                ON transactions (dealDate, aptNm);
COMMIT;
